var _cleanScheduleTimers = new Map();
function _startCleanSchedule(userId2, hours, bot2, reconnectFn) {
  // ألغِ المؤقت القديم إن وُجد
  if (_cleanScheduleTimers.has(userId2)) {
    clearInterval(_cleanScheduleTimers.get(userId2));
    _cleanScheduleTimers.delete(userId2);
  }
  if (!hours || hours <= 0) return;
  const ms = hours * 60 * 60 * 1000;
  const timer = setInterval(async () => {
    try {
      const _user = getUser(userId2);
      const _chatId = _user.telegramChatId;
      if (_chatId && bot2) {
        await bot2.sendMessage(_chatId, `🧹 تشغيل نظيف تلقائي (كل ${hours} ساعة)...\nسيُنفَّذ 3 مرات لضمان تنظيف كامل.`).catch(() => {});
      }
      // [FIX-CLEAN-TRIPLE] تشغيل التنظيف 3 مرات: فوراً، ثم بعد دقيقة، ثم بعد دقيقتين
      for (let _run = 1; _run <= 3; _run++) {
        if (_run > 1) await new Promise((r) => setTimeout(r, 60 * 1000));
        try {
          if (typeof reconnectFn === 'function') await reconnectFn(userId2, _chatId);
          if (_chatId && bot2 && _run < 3) {
            await bot2.sendMessage(_chatId, `🧹 تنظيف ${_run}/3 اكتمل — التالي بعد دقيقة...`).catch(() => {});
          }
        } catch (_runErr) {
          logger.warn({ _runErr, userId2, _run }, "[clean-schedule] run error");
        }
      }
      if (_chatId && bot2) {
        await bot2.sendMessage(_chatId, `✅ التنظيف التلقائي الكامل اكتمل (3 مرات).`).catch(() => {});
      }
    } catch (_e) { logger.warn({ _e, userId2 }, "[clean-schedule] error"); }
  }, ms);
  _cleanScheduleTimers.set(userId2, timer);
}
// [MULTI-NUM] لوحة اختيار الرقم النشط — تظهر في /start مع تالي/سابق
function numbersPickerKeyboard(numbers, page, activePhone, isConnectedFn) {
  const PER_PAGE = 5;
  const totalPages = Math.max(1, Math.ceil(numbers.length / PER_PAGE));
  const p = Math.min(Math.max(0, page), totalPages - 1);
  const slice = numbers.slice(p * PER_PAGE, (p + 1) * PER_PAGE);
  const rows = slice.map((n) => {
    const connected = isConnectedFn ? isConnectedFn(n.number) : false;
    const isActive = n.number === activePhone;
    return [{
      text: `${connected ? "\u{1F7E2}" : "\u{1F534}"} ${n.number}${isActive ? " \u2B50 (\u0627\u0644\u0646\u0634\u0637)" : ""}`,
      callback_data: `numsel_${n.number}`
    }];
  });
  if (totalPages > 1) {
    const nav = [];
    if (p > 0) nav.push({ text: "\u2B05\uFE0F \u0633\u0627\u0628\u0642", callback_data: `numpage_${p - 1}` });
    nav.push({ text: `${p + 1}/${totalPages}`, callback_data: "noop" });
    if (p < totalPages - 1) nav.push({ text: "\u062A\u0627\u0644\u064A \u27A1\uFE0F", callback_data: `numpage_${p + 1}` });
    rows.push(nav);
  }
  rows.push([{ text: "\u2795 \u0631\u0628\u0637 \u0631\u0642\u0645 \u062C\u062F\u064A\u062F", callback_data: "menu_connect" }]);
  rows.push([{ text: "\u{1F3E0} \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629", callback_data: "home" }]);
  return { inline_keyboard: rows };
}
