function featuresMenuKeyboard(tier, userPoints) {
  const tiers = ["pro", "promax", "khariq", "khariqpro", "mizaj"];
  const rows = tiers.map((t) => {
    const owned = isHigherOrEqualTier(tier, t);
    const cost = TIER_COSTS[t] || 0;
    const canAfford = userPoints >= cost;
    const emoji = owned ? "\u2705" : canAfford ? "\u{1F4B0}" : "\u{1F512}";
    const suffix = owned ? "\u0645\u0641\u0639\u0651\u0644" : `${cost.toLocaleString()} \u0646\u0642\u0637\u0629`;
    return [{ text: `${emoji} ${TIER_NAMES[t]} - ${suffix}`, callback_data: owned ? `feature_info_${t}` : `feature_buy_${t}` }];
  });
  rows.push([{ text: "\u2B50 \u0634\u0631\u0627\u0621 \u0645\u064A\u0632\u0627\u062C \u0628\u0640 1 \u0646\u062C\u0645\u0629 \u062A\u064A\u0644\u064A\u063A\u0631\u0627\u0645", callback_data: "buy_mizaj_stars" }]);
  rows.push(      [{ text: "مقارنة الباقات واختيار الأنسب", callback_data: "feature_bundle" }]);
  rows.push(backAndHome());
  return { inline_keyboard: rows };
}
function bundleKeyboard(userPoints) {
  const tiers = ["pro", "promax", "khariq", "khariqpro", "mizaj"];
  const rows = tiers.map((t) => [
    { text: `[ ] ${TIER_NAMES[t]} - ${TIER_COSTS[t].toLocaleString()} \u0646\u0642\u0637\u0629`, callback_data: `bundle_toggle_${t}` }
  ]);
  rows.push([{ text: "\u{1F4B0} \u0627\u062D\u062A\u0633\u0627\u0628 \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0648\u0627\u0644\u062E\u0635\u0645", callback_data: "bundle_calc" }]);
  rows.push([{ text: "\u{1F519} \u0631\u062C\u0648\u0639", callback_data: "back" }, { text: "\u274C \u0625\u0644\u063A\u0627\u0621", callback_data: "cancel" }]);
  return { inline_keyboard: rows };
}
