function groupListKeyboard(groups, page) {
  const perPage = 5;
  const totalPages = Math.max(1, Math.ceil(groups.length / perPage));
  const pageGroups = groups.slice(page * perPage, (page + 1) * perPage);
  const rows = pageGroups.map((g) => [{
    text: `\u{1F465} ${(g.subject || g.name || g.id || "\u0645\u062C\u0645\u0648\u0639\u0629").slice(0, 35)}`,
    callback_data: `groupinfo_${g.id}`
  }]);
  const nav = [];
  if (page > 0) nav.push({ text: "\u2B05\uFE0F \u0627\u0644\u0633\u0627\u0628\u0642", callback_data: `group_list_p${page - 1}` });
  nav.push({ text: `\u{1F4C4} ${page + 1}/${totalPages}`, callback_data: "noop" });
  if (page < totalPages - 1) nav.push({ text: "\u27A1\uFE0F \u0627\u0644\u062A\u0627\u0644\u064A", callback_data: `group_list_p${page + 1}` });
  if (nav.length) rows.push(nav);
  rows.push(backAndHome());
  return { inline_keyboard: rows };
}
