function contactsListKeyboard(contacts, page, action = "view") {
  const perPage = 8;
  const totalPages = Math.max(1, Math.ceil(contacts.length / perPage));
  const pageContacts = contacts.slice(page * perPage, (page + 1) * perPage);
  const rows = pageContacts.map((c) => {
    const safe = c.jid.replace(/[@.]/g, "_");
    const num = c.jid.split("@")[0];
    return [{ text: `\u{1F464} ${c.name || num} (+${num})`, callback_data: `contact_pick_${action}_${safe}` }];
  });
  const nav = [];
  if (page > 0) nav.push({ text: "\u2B05\uFE0F \u0627\u0644\u0633\u0627\u0628\u0642", callback_data: `contacts_p${page - 1}_${action}` });
  nav.push({ text: `\u{1F4C4} ${page + 1}/${totalPages} (${contacts.length})`, callback_data: "noop" });
  if (page < totalPages - 1) nav.push({ text: "\u27A1\uFE0F \u0627\u0644\u062A\u0627\u0644\u064A", callback_data: `contacts_p${page + 1}_${action}` });
  if (nav.length) rows.push(nav);
  rows.push([{ text: "\u{1F519} \u0631\u062C\u0648\u0639", callback_data: "menu_persons" }, { text: "\u{1F3E0} \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629", callback_data: "home" }]);
  return { inline_keyboard: rows };
}
