    const wordsList = bannedWords.length ? bannedWords.map((w) => `\u2022 ${w}`).join("\n") : "\u0644\u0627 \u062A\u0648\u062C\u062F \u0643\u0644\u0645\u0627\u062A \u0645\u062D\u0638\u0648\u0631\u0629";
