      const pathLib = await import("path");
      const botDir = process.cwd();
      const SKIP = new Set([".git", "node_modules", ".cache", ".local", ".upm", "__pycache__", ".pythonlibs", "venv"]);
      const EXT_SKIP = new Set([".log", ".tmp", ".pyc"]);
      const allFiles = [];
      function walkDir(dir) {
        let entries;
        try { entries = fsLib.readdirSync(dir); } catch(_) { return; }
        for (const entry of entries) {
          if (SKIP.has(entry)) continue;
          const full = pathLib.join(dir, entry);
          let stat;
          try { stat = fsLib.statSync(full); } catch(_) { continue; }
          if (stat.isDirectory()) {
            walkDir(full);
          } else {
            const ext = pathLib.extname(entry).toLowerCase();
            if (EXT_SKIP.has(ext)) continue;
            if (stat.size > 49 * 1024 * 1024) continue;
            const rel = pathLib.relative(botDir, full).replace(/\\/g, "/");
            allFiles.push({ rel, full, size: stat.size });
          }
        }
      }
