function getSettings(user) {
  return { ...DEFAULT_SETTINGS, ...user.msgSettings || {} };
}
function saveSettings(userId, settings) {
  const user = getUser(userId);
  const current = getSettings(user);
  const updated = { ...current, ...settings };
  saveUser(userId, { msgSettings: updated });
  return updated;
}
