    await bot2.sendMessage(chatId, `\u2705 \u0627\u0644\u0625\u062C\u0631\u0627\u0621: ${next === "ignore" ? "\u062A\u062C\u0627\u0647\u0644" : next === "reply" ? "\u0631\u062F" : "\u062D\u0638\u0631"}`);
