async function handleNumbersCallback(bot2, chatId, userId, data) {
  const user = getUser(userId);
  const isDev2 = userId === DEVELOPER_ID;
  if (data === "menu_numbers") {
    const nums = getUserNumbers(userId);
    const connected = nums.filter((n) => n.status === "active").length;
    await bot2.sendMessage(
      chatId,
      `\u{1F4F1} *\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0623\u0631\u0642\u0627\u0645*

\u{1F4CA} \u0623\u0631\u0642\u0627\u0645\u0643: ${nums.length}/${user.maxNumbers || 1}
\u{1F7E2} \u0646\u0634\u0637: ${connected}

${nums.map(
        (n, i) => `${i + 1}. ${n.status === "active" ? "\u{1F7E2}" : "\u{1F534}"} +${n.number}
   \u{1F3F7}\uFE0F ${n.label || "\u0628\u062F\u0648\u0646 \u0627\u0633\u0645"}`
      ).join("\n\n") || "\u0644\u0627 \u062A\u0648\u062C\u062F \u0623\u0631\u0642\u0627\u0645 \u0645\u064F\u0636\u0627\u0641\u0629."}`,
      { parse_mode: "Markdown", reply_markup: numbersManagerKeyboard(nums) }
    );
    return true;
  }
  if (data === "numbers_add") {
    const nums = getUserNumbers(userId);
    if (nums.length >= (user.maxNumbers || 1)) {
      await bot2.sendMessage(
        chatId,
        `\u274C *\u0648\u0635\u0644\u062A \u0644\u0644\u062D\u062F \u0627\u0644\u0623\u0642\u0635\u0649 (${nums.length}/${user.maxNumbers || 1})*

\u0642\u0645 \u0628\u062A\u0631\u0642\u064A\u0629 \u0628\u0627\u0642\u062A\u0643 \u0623\u0648 \u0634\u0631\u0627\u0621 \u0631\u0642\u0645 \u0625\u0636\u0627\u0641\u064A \u0628\u0640 50,000 \u0646\u0642\u0637\u0629.`,
        { parse_mode: "Markdown" }
      );
      return true;
    }
    await bot2.sendMessage(chatId, "\u{1F4F1} *\u0625\u0636\u0627\u0641\u0629 \u0631\u0642\u0645 \u062C\u062F\u064A\u062F*\n\n\u0627\u062E\u062A\u0631 \u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u0631\u0628\u0637:", {
      parse_mode: "Markdown",
      reply_markup: {
        inline_keyboard: [
          [{ text: "\u{1F4F7} QR Code", callback_data: "connect_qr" }, { text: "\u{1F522} \u0631\u0642\u0645 \u0647\u0627\u062A\u0641", callback_data: "connect_pairing" }],
          [{ text: "\u{1F519} \u0631\u062C\u0648\u0639", callback_data: "menu_numbers" }]
        ]
      }
    });
    return true;
  }
  if (data === "numbers_settings") {
    const nums = getUserNumbers(userId);
    if (nums.length === 0) {
      await bot2.sendMessage(chatId, "\u274C \u0644\u0627 \u062A\u0648\u062C\u062F \u0623\u0631\u0642\u0627\u0645");
      return true;
    }
    const rows = nums.map((n) => [{
      text: `\u2699\uFE0F +${n.number} ${n.status === "active" ? "\u{1F7E2}" : "\u{1F534}"}`,
      callback_data: `num_cfg_${n.id}`
    }]);
    rows.push([{ text: "\u{1F519} \u0631\u062C\u0648\u0639", callback_data: "menu_numbers" }]);
    await bot2.sendMessage(chatId, "\u2699\uFE0F \u0627\u062E\u062A\u0631 \u0627\u0644\u0631\u0642\u0645 \u0644\u062A\u0639\u062F\u064A\u0644 \u0625\u0639\u062F\u0627\u062F\u0627\u062A\u0647:", { reply_markup: { inline_keyboard: rows } });
    return true;
  }
  if (data.startsWith("num_cfg_")) {
    const numId = data.replace("num_cfg_", "");
    const nums = getUserNumbers(userId);
    const num = nums.find((n) => n.id === numId);
    if (!num) {
      await bot2.sendMessage(chatId, "\u274C \u0627\u0644\u0631\u0642\u0645 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F");
      return true;
    }
    await bot2.sendMessage(
      chatId,
      `\u2699\uFE0F *\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0631\u0642\u0645 +${num.number}*

\u0627\u0644\u062D\u0627\u0644\u0629: ${num.status === "active" ? "\u{1F7E2} \u0646\u0634\u0637" : "\u{1F534} \u063A\u064A\u0631 \u0646\u0634\u0637"}
\u0627\u0644\u0627\u0633\u0645: ${num.label || "\u0628\u062F\u0648\u0646 \u0627\u0633\u0645"}
\u0627\u0644\u0638\u0647\u0648\u0631 \u0627\u0644\u0645\u0633\u062A\u0645\u0631: ${num.alwaysOnline ? "\u2705" : "\u274C"}`,
      { parse_mode: "Markdown", reply_markup: numberDetailKeyboard(numId, num) }
    );
    return true;
  }
  if (data.startsWith("num_label_")) {
    const numId = data.replace("num_label_", "");
    setState(userId, "awaiting_num_label", { numId });
    await bot2.sendMessage(chatId, "\u{1F3F7}\uFE0F \u0623\u062F\u062E\u0644 \u0627\u0644\u0627\u0633\u0645/\u0627\u0644\u062A\u0633\u0645\u064A\u0629 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u0644\u0644\u0631\u0642\u0645:", { reply_markup: cancelKeyboard() });
    return true;
  }
  if (data.startsWith("num_delete_")) {
    const numId = data.replace("num_delete_", "");
    const nums = getUserNumbers(userId);
    const num = nums.find((n) => n.id === numId);
    if (num) {
      removeNumber(userId, numId);
      await bot2.sendMessage(chatId, `\u2705 \u062A\u0645 \u062D\u0630\u0641 \u0631\u0642\u0645 +${num.number}`);
    }
    return true;
  }
  if (data.startsWith("num_set_primary_")) {
    const numId = data.replace("num_set_primary_", "");
    const nums = getUserNumbers(userId);
    for (const n of nums) {
      await updateNumber(userId, n.id, { ...n, isPrimary: n.id === numId });
    }
    const target = nums.find((n) => n.id === numId);
    await bot2.sendMessage(chatId, `\u2705 \u062A\u0645 \u062A\u0639\u064A\u064A\u0646 +${target?.number} \u0643\u0631\u0642\u0645 \u0631\u0626\u064A\u0633\u064A`);
    return true;
  }
  if (data.startsWith("num_toggle_online_")) {
    const numId = data.replace("num_toggle_online_", "");
    const nums = getUserNumbers(userId);
    const num = nums.find((n) => n.id === numId);
    if (num) {
      const newVal = !num.alwaysOnline;
      await updateNumber(userId, numId, { ...num, alwaysOnline: newVal });
      const { setAlwaysOnline: setAlwaysOnline2 } = await Promise.resolve().then(() => (init_baileys_session(), baileys_session_exports));
      setAlwaysOnline2(userId, newVal);
      await bot2.sendMessage(chatId, `\u{1F310} \u0627\u0644\u0638\u0647\u0648\u0631 \u0627\u0644\u0645\u0633\u062A\u0645\u0631 \u0644\u0644\u0631\u0642\u0645 +${num.number}: ${newVal ? "\u2705 \u0645\u0641\u0639\u0651\u0644" : "\u274C \u0645\u0639\u0637\u0651\u0644"}`);
    }
    return true;
  }
  if (data === "numbers_stats") {
    const nums = getUserNumbers(userId);
    const active = nums.filter((n) => n.status === "active").length;
    await bot2.sendMessage(
      chatId,
      `\u{1F4CA} *\u0625\u062D\u0635\u0627\u0626\u064A\u0627\u062A \u0627\u0644\u0623\u0631\u0642\u0627\u0645*

\u{1F4F1} \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A: ${nums.length}
\u{1F7E2} \u0646\u0634\u0637: ${active}
\u{1F534} \u063A\u064A\u0631 \u0646\u0634\u0637: ${nums.length - active}
\u{1F4F1} \u0627\u0644\u062D\u062F \u0627\u0644\u0645\u0633\u0645\u0648\u062D: ${user.maxNumbers || 1}`,
      { parse_mode: "Markdown" }
    );
    return true;
  }
  if (data === "menu_lookup") {
    const { phoneLookupKeyboard: phoneLookupKeyboard2 } = await Promise.resolve().then(() => (init_keyboards(), keyboards_exports));
    const { getLookupCount: getLookupCount2, getLookupLimit: getLookupLimit2 } = await Promise.resolve().then(() => (init_phone_lookup(), phone_lookup_exports));
    const { count } = getLookupCount2(userId);
    const limit = getLookupLimit2(user.tier);
    const limitText = limit === Infinity ? "\u221E" : String(limit);
    await bot2.sendMessage(
      chatId,
      `\u{1F50D} *\u0628\u062D\u062B \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0631\u0642\u0645*

\u2022 \u064A\u0643\u0634\u0641 \u0627\u0644\u0628\u0644\u062F\u060C \u0627\u0644\u0645\u0634\u063A\u0651\u0644\u060C \u0648\u062C\u0648\u062F \u0641\u064A \u0648\u0627\u062A\u0633\u0627\u0628\u060C \u0627\u0644\u0627\u0633\u0645
\u2022 \u0628\u062D\u062B\u0643 \u0627\u0644\u064A\u0648\u0645: ${count}/${limitText}

\u{1F4CA} \u0627\u0644\u062D\u062F\u0648\u062F \u0627\u0644\u064A\u0648\u0645\u064A\u0629:
\u2022 \u0645\u062C\u0627\u0646\u064A: 5 | Pro: 10 | ProMax: 20
\u2022 \u062E\u0627\u0631\u0642: 30 | \u0645\u064A\u0632\u0627\u062C: \u221E`,
      { parse_mode: "Markdown", reply_markup: phoneLookupKeyboard2() }
    );
    return true;
  }
  if (data === "lookup_search") {
    const { getLookupCount: getLookupCount2, getLookupLimit: getLookupLimit2 } = await Promise.resolve().then(() => (init_phone_lookup(), phone_lookup_exports));
    const { count } = getLookupCount2(userId);
    const limit = getLookupLimit2(user.tier);
    if (count >= limit) {
      await bot2.sendMessage(chatId, `\u274C \u0648\u0635\u0644\u062A \u0644\u0644\u062D\u062F \u0627\u0644\u064A\u0648\u0645\u064A (${count}/${limit === Infinity ? "\u221E" : limit})

\u0631\u0642\u0651 \u0628\u0627\u0642\u062A\u0643 \u0644\u0632\u064A\u0627\u062F\u0629 \u0627\u0644\u0639\u062F\u062F.`, { parse_mode: "Markdown" });
      return true;
    }
    setState(userId, "awaiting_phone_lookup");
    await bot2.sendMessage(
      chatId,
      `\u{1F50D} \u0623\u062F\u062E\u0644 \u0627\u0644\u0631\u0642\u0645 \u0645\u0639 \u0643\u0648\u062F \u0627\u0644\u062F\u0648\u0644\u0629:
\u0645\u062B\u0627\u0644: \`966501234567\``,
      { parse_mode: "Markdown", reply_markup: cancelKeyboard() }
    );
    return true;
  }
  if (data === "lookup_stats") {
    const { getLookupCount: getLookupCount2, getLookupLimit: getLookupLimit2 } = await Promise.resolve().then(() => (init_phone_lookup(), phone_lookup_exports));
    const { count } = getLookupCount2(userId);
    const limit = getLookupLimit2(user.tier);
    const limitText = limit === Infinity ? "\u221E" : String(limit);
    await bot2.sendMessage(
      chatId,
      `\u{1F4CA} *\u0625\u062D\u0635\u0627\u0626\u064A\u0627\u062A \u0627\u0644\u0628\u062D\u062B*

b\u062D\u0648\u062B \u0627\u0644\u064A\u0648\u0645: ${count}/${limitText}
\u0641\u0626\u062A\u0643: ${user.tier}`,
      { parse_mode: "Markdown" }
    );
    return true;
  }
  return false;
}

