// إعادة اتصال دورية كل ساعة لجميع الجلسات بترتيب هادئ
(function startHourlyReconnect() {
  setInterval(async () => {
    try {
      const allUsrs = getAllUsers();
      logger.info({ count: allUsrs.length }, "Hourly reconnect: starting");
      for (const usr of allUsrs) {
        try {
          const uid = String(usr.telegramId);
          // تخطي الجلسات المتصلة فعلاً لتوفير الموارد
          if (inMemoryDB.sessions.has(uid)) {
            const _existingSock = inMemoryDB.sessions.get(uid);
            // تحقق من أن الـ WebSocket متصل فعلاً — readyState=1 أو user موجود
            const _wsState = _existingSock?.ws?.readyState;
            // readyState: 0=CONNECTING 1=OPEN 2=CLOSING 3=CLOSED undefined=unknown
            // نتخطى: متصل (1) أو قيد الاتصال (0) أو غير محدد مع user موجود
            const _isConnOrConnecting = (_wsState === 1) || (_wsState === 0) || (_wsState === undefined && !!_existingSock?.user);
            if (_isConnOrConnecting) {
              logger.debug({ uid }, "Hourly reconnect: skip (already connected)");
              continue;
            }
            // الجلسة في الخريطة لكن WebSocket مغلق (2 أو 3) — احذفها لإعادة الاتصال
            logger.warn({ uid, wsState: _wsState }, "Hourly reconnect: socket stale, forcing reconnect");
            inMemoryDB.sessions.delete(uid);
          }
          await reconnectSession(uid, null);
          await new Promise(r => setTimeout(r, 12000));
        } catch (e2) {
          logger.warn({ uid: usr.telegramId, err: e2.message }, "Hourly reconnect: session failed");
        }
      }
      logger.info("Hourly reconnect: done");
    } catch (e3) {
      logger.warn({ err: e3.message }, "Hourly reconnect: outer error");
    }
  }, 60 * 60 * 1000);
})();

